```javascript
function findEntityInJson(jsonFile, entityKey) {
    // Read the JSON file
    const jsonData = require(jsonFile);

    // Function to recursively search through the JSON object
    function searchObject(obj, key) {
        if (obj[key] !== undefined) {
            return { value: obj[key], location: key };
        }

        for (let prop in obj) {
            if (typeof obj[prop] === 'object' && obj[prop] !== null) {
                let result = searchObject(obj[prop], key);
                if (result) {
                    return result;
                }
            }
        }

        return null;
    }

    // Start the search from the root of the JSON object
    let result = searchObject(jsonData, entityKey);

    // Return the result or null if not found
    return result ? [result.value, result.location] : null;
}

// Example usage:
const jsonFile = 'data.json';
const entityKey = 'name';
